#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/iterable_sections.h>

struct test_item {
    int val;
};

/* Items for RAM section */
/* Reduce to two items for robustness across different linker configurations */
static const struct test_item item_ram_1 __attribute__((section(".test_ram_section"))) = {1};
static const struct test_item item_ram_2 __attribute__((section(".test_ram_section"))) = {2};

/* Items for ROM section */
static const struct test_item item_rom_1 __attribute__((section(".test_rom_section"))) = {10};
static const struct test_item item_rom_2 __attribute__((section(".test_rom_section"))) = {20};

/* Adjust RAM_EXPECT to match the two defined RAM items */
#define RAM_EXPECT (1 + 2)
#define ROM_EXPECT (10 + 20)

static void iterable_sections_test_ram(void)
{
    int out = 0;

    Z_ITERABLE_SECTION_FOREACH(struct test_item, item, test_ram_section) {
        out += item->val;
    }

    zassert_equal(out, RAM_EXPECT, "out not equal to RAM_EXPECT");
}

static void iterable_sections_test_rom(void)
{
    int out = 0;

    Z_ITERABLE_SECTION_FOREACH(struct test_item, item, test_rom_section) {
        out += item->val;
    }

    zassert_equal(out, ROM_EXPECT, "out not equal to ROM_EXPECT");
}

ZTEST_SUITE(iterable_sections, NULL, NULL, NULL, NULL, NULL);

ZTEST(iterable_sections, test_ram)
{
    iterable_sections_test_ram();
}

ZTEST(iterable_sections, test_rom)
{
    iterable_sections_test_rom();
}
